// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
  random,
} from '../remotionShim';
// Load Google Fonts
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
const loadInter = makeLoadFont('Inter');

const { fontFamily: spaceFont } = loadSpaceGrotesk();
const { fontFamily: interFont } = loadInter();



export type DateTimelapseProps = Record<string, any>;

const DateTimelapse: React.FC<DateTimelapseProps> = ({
  backgroundColor = "#070707",
  transparentBackground = false,
  durationInSeconds = 8,
  startYear = 2024,
  endYear = -3000,
  titleText = "TEMPORAL DISPLACEMENT",
  destinationText = "EARLY BRONZE AGE",
  textColor = "#FFFFFF",
  accentColor = "#FF5500",
  showTimelineGrid = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parse background
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  const totalFrames = durationInSeconds * fps;

  // Animation Timings
  const timeJumpStartFrame = totalFrames * 0.15; // 15% mark
  const timeJumpEndFrame = totalFrames * 0.85; // 85% mark

  // Non-linear progress for the time jump (Cubic Ease In/Out)
  const jumpProgress = interpolate(
    frame,
    [timeJumpStartFrame, timeJumpEndFrame],
    [0, 1],
    {
      easing: Easing.inOut(Easing.cubic),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Calculate Current Year
  const currentYearRaw = interpolate(jumpProgress, [0, 1], [startYear, endYear]);
  const displayYear = Math.abs(Math.round(currentYearRaw));
  const isBCE = currentYearRaw < 0;
  const suffix = isBCE ? "BCE" : "CE";

  // Intensity Curve (0 -> 1 -> 0) peaking in the middle of the jump
  const intensity = Math.sin(jumpProgress * Math.PI);

  // Camera/Text Jitter based on intensity (scaled down for smaller animation)
  const jitterX = (random(`x-${frame}`) * 2 - 1) * 12 * intensity;
  const jitterY = (random(`y-${frame}`) * 2 - 1) * 12 * intensity;
  const scale = 1 + intensity * 0.06;

  // Timeline Grid Calculations (Horizontal lines moving vertically)
  const direction = startYear > endYear ? -1 : 1;
  const totalDistance = jumpProgress * 25000 * direction;
  const numLines = 18;
  const lineGap = height / numLines;

  // Destination Text Fade In (only appears at the end)
  const destOpacity = interpolate(
    frame,
    [timeJumpEndFrame, timeJumpEndFrame + fps * 0.5],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Background Timeline Grid */}
      {showTimelineGrid &&
        Array.from({ length: numLines }).map((_, i) => {
          const rawY = (totalDistance + i * lineGap) % height;
          // Handle negative modulo correctly
          const y = rawY < 0 ? rawY + height : rawY;

          // Fade out near the top and bottom edges
          const lineOpacity = interpolate(
            y,
            [0, height * 0.1, height * 0.9, height],
            [0, 0.4, 0.4, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Render horizontal line spanning the canvas width (scaled down)
          return (
            <div
              key={i}
              style={{
                position: "absolute",
                top: y,
                left: width * 0.2,
                width: width * 0.6,
                height: 2,
                backgroundColor: accentColor,
                opacity: lineOpacity,
                boxShadow: `0 0 10px ${accentColor}`,
                transition: "none",
              }}
            />
          );
        })}

      {/* Main Content Container */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          width: "100%",
          height: "100%",
          transform: `translate(${jitterX}px, ${jitterY}px) scale(${scale})`,
          transition: "none",
        }}
      >
        {/* Top Title */}
        <div
          style={{
            fontFamily: interFont,
            fontSize: width * 0.024,
            color: textColor,
            letterSpacing: "0.2em",
            opacity: 0.7,
            marginBottom: height * 0.05,
            transition: "none",
          }}
        >
          {titleText}
        </div>

        {/* The Year Display */}
        <div
          style={{
            fontFamily: spaceFont,
            fontWeight: 700,
            fontSize: width * 0.21,
            color: textColor,
            lineHeight: 0.9,
            textShadow: `0 0 ${intensity * 30}px ${accentColor}`,
            transition: "none",
            display: "flex",
            alignItems: "baseline",
            gap: width * 0.024,
          }}
        >
          <span>{displayYear}</span>
          <span
            style={{
              fontSize: width * 0.06,
              opacity: 0.8,
              letterSpacing: "0.1em",
            }}
          >
            {suffix}
          </span>
        </div>

        {/* Speed / Tech Details overlay (visible only during jump) */}
        <div
          style={{
            marginTop: height * 0.03,
            fontFamily: spaceFont,
            fontSize: width * 0.021,
            color: accentColor,
            letterSpacing: "0.15em",
            opacity: intensity,
            transition: "none",
          }}
        >
          {Math.round(intensity * 8500)} YRS / SEC
        </div>

        {/* Destination Arrival Text */}
        <div
          style={{
            position: "absolute",
            bottom: height * 0.15,
            fontFamily: interFont,
            fontSize: width * 0.03,
            color: textColor,
            letterSpacing: "0.1em",
            opacity: destOpacity,
            fontWeight: 600,
            padding: "8px 24px",
            border: `2px solid ${accentColor}`,
            borderRadius: "50px",
            backgroundColor: `${backgroundColor}CC`,
            transition: "none",
          }}
        >
          {destinationText}
        </div>
      </div>

      {/* Vignette Overlay for Depth */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          pointerEvents: "none",
          background: `radial-gradient(circle at center, transparent 30%, #000000 120%)`,
          opacity: 0.8,
          transition: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default DateTimelapse;